   1→/**
   2→ * Calibration State — The Translators v5
   3→ *
   4→ * GROWING YOUR GARDEN
   5→ *
   6→ * A vintage Macintosh sits in darkness. You answer questions about yourself.
   7→ * With each answer, life appears:
   8→ *
   9→ * Stage 1 (Q1-2): SEEDS — Glowing motes drift down, plant themselves, wait
  10→ * Stage 2 (Q3-4): SPROUTS — Stems rise from seeds, tendrils reach out, first leaves unfurl
  11→ * Stage 3 (Q5-6): BLOOM — Flowers open their petals, moths flutter in, color arrives
  12→ * Stage 4 (Q7-8): GLOW — Bioluminescence pulses through everything, fireflies dance, the garden breathes
  13→ *
  14→ * The Mac is the seed. The garden is YOU becoming visible.
  15→ * By the end, you're surrounded by a living world you grew from answers.
  16→ *
  17→ * This is not a metaphor. Seeds LITERALLY plant. Stems LITERALLY grow.
  18→ * Flowers LITERALLY open. You watch yourself become a garden.
  19→ *
  20→ * DETERMINISM: The cognitive profile is computed via DeterministicProfileEngine.
  21→ * Same answers → Same profile. Always. The garden can vary (aesthetic),
  22→ * but the traits are invariant.
  23→ */
  24→
  25→import { DeterministicProfileEngine } from '../systems/DeterministicProfileEngine.js';
  26→import { PixelGarden, PixelRenderer, PALETTE } from '../systems/PixelGarden.js';
  27→import {
  28→  CognitiveCalibrationManager,
  29→  formatCognitiveQuestionForDisplay,
  30→  getCognitiveDepthLabel
  31→} from '../calibration/index.js';
  32→
  33→/**
  34→ * The Questions — Honest calibration for USD Cognitive Substrate
  35→ *
  36→ * Each question maps to a USD parameter:
  37→ * - Q1: LOAD → cognitive_density
  38→ * - Q2: GROUND → home_altitude
  39→ * - Q3: LEASH → guidance_frequency
  40→ * - Q4: LOST → default_paradigm
  41→ * - Q5: WRONG → feedback_expert
  42→ * - Q6: FOG → uncertainty_tolerance
  43→ * - Q7: SILENCE → processing_pace
  44→ * - Q8: WANDER → tangent_budget
  45→ */
  46→const QUESTIONS = [
  47→  // STAGE 1: SURFACE — How your mind works when it's working
  48→  {
  49→    id: 'load',
  50→    text: "How much can you hold at once\nbefore it starts to blur?",
  51→    options: [
  52→      { label: "Not much. One thing at a time.", value: 'low', trait: 0.2 },
  53→      { label: "Quite a lot. I can hold complexity.", value: 'high', trait: 0.8 },
  54→      { label: "It varies. Some days more than others.", value: 'adaptive', trait: 0.5 }
  55→    ],
  56→    dimension: 'cognitive_density',
  57→    depth: 1
  58→  },
  59→  {
  60→    id: 'ground',
  61→    text: "Where does your mind live?",
  62→    options: [
  63→      { label: "In the details. Ground level. Show me the thing.", value: 'ground', trait: 0.2 },
  64→      { label: "In the big picture. Why before how.", value: 'high', trait: 0.8 },
  65→      { label: "I move between them. Zoom in, zoom out.", value: 'mid', trait: 0.5 }
  66→    ],
  67→    dimension: 'home_altitude',
  68→    depth: 1
  69→  },
  70→
  71→  // STAGE 2: PATTERNS — How you move when you're stuck
  72→  {
  73→    id: 'leash',
  74→    text: "How long is the leash?",
  75→    options: [
  76→      { label: "Short. Check in often. I like the tether.", value: 'short', trait: 0.8 },
  77→      { label: "Long. Trust me to run. I'll call if I need you.", value: 'long', trait: 0.2 },
  78→      { label: "It depends. Read the situation.", value: 'adaptive', trait: 0.5 }
  79→    ],
  80→    dimension: 'guidance_frequency',
  81→    depth: 2
  82→  },
  83→  {
  84→    id: 'lost',
  85→    text: "When you're lost,\ndo you search wide or dig deep?",
  86→    options: [
  87→      { label: "Wide. The answer might be somewhere unexpected.", value: 'wide', trait: 0.8 },
  88→      { label: "Deep. Narrow down. Eliminate. Focus.", value: 'deep', trait: 0.2 },
  89→      { label: "I feel my way. Intuition guides me.", value: 'intuition', trait: 0.5 }
  90→    ],
  91→    dimension: 'default_paradigm',
  92→    depth: 2
  93→  },
  94→
  95→  // STAGE 3: FEELINGS — How you handle the hard parts
  96→  {
  97→    id: 'wrong',
  98→    text: "When you're wrong,\nhow should I tell you?",
  99→    options: [
 100→      { label: "Straight. Just say it.", value: 'direct', trait: 0.2 },
 101→      { label: "Through questions. Help me see it myself.", value: 'socratic', trait: 0.5 },
 102→      { label: "Gently. Wrap it in something soft.", value: 'gentle', trait: 0.8 }
 103→    ],
 104→    dimension: 'feedback_style',
 105→    depth: 3
 106→  },
 107→  {
 108→    id: 'fog',
 109→    text: "Can you sit in the fog?",
 110→    options: [
 111→      { label: "No. It eats at me. Give me something to hold onto.", value: 'no', trait: 0.2 },
 112→      { label: "Yes. I can wait. Clarity comes when it comes.", value: 'yes', trait: 0.8 },
 113→      { label: "Depends what's at stake. Some fog is fine.", value: 'depends', trait: 0.5 }
 114→    ],
 115→    dimension: 'uncertainty_tolerance',
 116→    depth: 3
 117→  },
 118→
 119→  // STAGE 4: CORE — How you move through time
 120→  {
 121→    id: 'silence',
 122→    text: "When neither of us is talking,\nis that a problem?",
 123→    options: [
 124→      { label: "Yes. Fill the space. Silence is uncomfortable.", value: 'yes', trait: 0.2 },
 125→      { label: "No. We're thinking. This is productive.", value: 'no', trait: 0.8 },
 126→      { label: "Sometimes. Depends if we're stuck or processing.", value: 'sometimes', trait: 0.5 }
 127→    ],
 128→    dimension: 'processing_pace',
 129→    depth: 4
 130→  },
 131→  {
 132→    id: 'wander',
 133→    text: "When we wander off the path,\nis that discovery or distraction?",
 134→    options: [
 135→      { label: "Discovery. The good stuff lives in the margins.", value: 'discovery', trait: 0.9 },
 136→      { label: "Distraction. Let's finish what we started.", value: 'distraction', trait: 0.2 },
 137→      { label: "Depends. Interesting tangents yes, boring ones no.", value: 'selective', trait: 0.5 }
 138→    ],
 139→    dimension: 'tangent_tolerance',
 140→    depth: 4
 141→  }
 142→];
 143→
 144→export class CalibrationState {
 145→  constructor() {
 146→    // UI
 147→    this.container = null;
 148→
 149→    // Question state
 150→    this.currentQuestionIndex = 0;
 151→    this.answers = {};
 152→
 153→    // Evolution state (0-1, increases with each question)
 154→    this.evolution = 0;
 155→    this.targetEvolution = 0;
 156→    this.stage = 0; // 1-4, which stage of growth
 157→
 158→    // === THE PIXEL GARDEN ===
 159→    // GROW-A-GARDEN style with individual plants
 160→    this.garden = null;
 161→    this.pixelRenderer = null;
 162→
 163→    // Stars (kept separate - they're sky, not garden)
 164→    this.stars = [];
 165→
 166→    // Ambient effects
 167→    this.ambientGlow = 0;
 168→    this.time = 0;
 169→
 170→    // Visual parameters that evolve
 171→    this.brightness = 0.1;     // Very dark start
 172→    this.windPhase = 0;
 173→
 174→    // Mac bounds
 175→    this.macBounds = { x: 0, y: 0, width: 0, height: 0 };
 176→    this.screenBounds = { x: 0, y: 0, width: 0, height: 0 };
 177→
 178→    // Ground line (where plants grow)
 179→    this.groundY = 0;
 180→
 181→    // ZEN: Cursor tracking for presence response
 182→    this.cursorX = null;
 183→    this.cursorY = null;
 184→
 185→    // === COGNITIVE PROFILING ===
 186→    // Deep cognitive profile built alongside legacy questions
 187→    this.cognitiveManager = null;
 188→    this.phase = 'legacy'; // 'legacy' | 'cognitive' | 'complete'
 189→    this.currentCognitiveQuestion = null;
 190→  }
 191→
 192→  enter(game) {
 193→    this.currentQuestionIndex = 0;
 194→    this.answers = {};
 195→    this.time = 0;
 196→
 197→    // Reset evolution state
 198→    this.evolution = 0;
 199→    this.targetEvolution = 0;
 200→    this.stage = 0;
 201→    this.brightness = 0.1;
 202→    this.windPhase = 0;
 203→    this.ambientGlow = 0;
 204→
 205→    // === COGNITIVE PROFILING ===
 206→    // Try to load existing profile, or create new one
 207→    this.cognitiveManager = CognitiveCalibrationManager.loadFromStorage();
 208→    this.cognitiveManager.startSession();
 209→    this.phase = 'legacy';
 210→    this.currentCognitiveQuestion = null;
 211→
 212→    this.calculateBounds(game);
 213→
 214→    // Ground is lower portion of screen
 215→    this.groundY = game.height * 0.75;
 216→
 217→    // === INITIALIZE PIXEL GARDEN ===
 218→    this.garden = new PixelGarden(game.width, game.height, this.groundY);
 219→    // Renderer is set during render() since we need ctx
 220→
 221→    // Initialize stars (invisible at first, fade in with evolution)
 222→    this.stars = [];
 223→    this.initStars(game);
 224→
 225→    this.createUI(game);
 226→    this.showQuestion(game, 0);
 227→  }
 228→
 229→  exit(game) {
 230→    if (this.container) {
 231→      this.container.remove();
 232→    }
 233→  }
 234→
 235→  calculateBounds(game) {
 236→    // 2.0x SCALE for LARGER, more prominent Mac (was 1.5x)
 237→    const scale = 2.0;
 238→    const macHeight = Math.min(520, game.height * 0.6) * scale;
 239→    const macWidth = macHeight * 0.85;
 240→
 241→    // 3D DEPTH parameters
 242→    this.depthOffset = macHeight * 0.08; // How much depth to show
 243→    this.depthAngle = 0.15; // Slight perspective skew
 244→
 245→    this.macBounds = {
 246→      x: (game.width - macWidth) / 2,
 247→      y: (game.height - macHeight) / 2 - this.depthOffset / 2, // Adjust for depth
 248→      width: macWidth,
 249→      height: macHeight
 250→    };
 251→
 252→    const bezelTop = macHeight * 0.10;
 253→    const bezelSide = macWidth * 0.08;
 254→    const bezelBottom = macHeight * 0.22;
 255→
 256→    this.screenBounds = {
 257→      x: this.macBounds.x + bezelSide,
 258→      y: this.macBounds.y + bezelTop,
 259→      width: macWidth - bezelSide * 2,
 260→      height: macHeight - bezelTop - bezelBottom
 261→    };
 262→  }
 263→
 264→  // === STARS ===
 265→
 266→  initStars(game) {
 267→    // Stars are always there, but invisible until evolution brings light
 268→    const starCount = 60 + Math.floor(Math.random() * 40);
 269→    for (let i = 0; i < starCount; i++) {
 270→      this.stars.push({
 271→        x: Math.random() * game.width,
 272→        y: Math.random() * this.groundY * 0.6, // Upper sky only
 273→        size: 0.5 + Math.random() * 1.5,
 274→        twinklePhase: Math.random() * Math.PI * 2,
 275→        twinkleSpeed: 0.5 + Math.random() * 2,
 276→        brightness: 0.3 + Math.random() * 0.7
 277→      });
 278→    }
 279→  }
 280→
 281→  createUI(game) {
 282→    this.injectStyles();
 283→
 284→    this.container = document.createElement('div');
 285→    this.container.className = 'calibration-container';
 286→    this.container.innerHTML = `
 287→      <div class="mac-question-overlay" id="questionOverlay">
 288→        <div class="question-header">
 289→          <div class="question-progress" id="progress"></div>
 290→          <div class="question-depth" id="depth"></div>
 291→        </div>
 292→        <div class="question-text" id="questionText"></div>
 293→        <div class="question-options" id="options"></div>
 294→      </div>
 295→    `;
 296→
 297→    game.ui.appendChild(this.container);
 298→  }
 299→
 300→  showQuestion(game, index) {
 301→    // Check if we've finished legacy questions
 302→    if (index >= QUESTIONS.length) {
 303→      // Transition to cognitive phase (optional deep questions)
 304→      if (this.phase === 'legacy' && this.cognitiveManager) {
 305→        this.phase = 'cognitive';
 306→        this.showCognitiveQuestion(game);
 307→        return;
 308→      }
 309→      this.finishCalibration(game);
 310→      return;
 311→    }
 312→
 313→    const q = QUESTIONS[index];
 314→    const overlay = this.container.querySelector('#questionOverlay');
 315→    const progress = this.container.querySelector('#progress');
 316→    const depth = this.container.querySelector('#depth');
 317→    const text = this.container.querySelector('#questionText');
 318→    const options = this.container.querySelector('#options');
 319→
 320→    // Position overlay
 321→    overlay.style.left = `${this.screenBounds.x + 8}px`;
 322→    overlay.style.top = `${this.screenBounds.y + 8}px`;
 323→    overlay.style.width = `${this.screenBounds.width - 16}px`;
 324→    overlay.style.height = `${this.screenBounds.height - 16}px`;
 325→
 326→    // Depth indicators
 327→    const depthLabels = ['Surface', 'Patterns', 'Feelings', 'Core'];
 328→    progress.textContent = `${index + 1}/${QUESTIONS.length}`;
 329→    depth.textContent = depthLabels[q.depth - 1];
 330→    depth.className = `question-depth depth-${q.depth}`;
 331→
 332→    text.textContent = q.text;
 333→
 334→    options.innerHTML = q.options.map((opt, i) => `
 335→      <button class="mac-option" data-index="${i}" data-value="${opt.value}" data-trait="${opt.trait}">
 336→        ${opt.label}
 337→      </button>
 338→    `).join('');
 339→
 340→    options.querySelectorAll('.mac-option').forEach(btn => {
 341→      btn.onclick = () => this.selectAnswer(game, q, btn.dataset);
 342→    });
 343→
 344→    // Track question presentation for behavioral analysis
 345→    if (this.cognitiveManager) {
 346→      this.cognitiveManager.onLegacyQuestionPresented(q.id);
 347→    }
 348→
 349→    // Fade in
 350→    overlay.classList.remove('visible');
 351→    setTimeout(() => overlay.classList.add('visible'), 50);
 352→  }
 353→
 354→  selectAnswer(game, question, data) {
 355→    const answer = {
 356→      value: data.value,
 357→      trait: parseFloat(data.trait),
 358→      dimension: question.dimension,
 359→      depth: question.depth
 360→    };
 361→    this.answers[question.id] = answer;
 362→
 363→    // Track answer in cognitive manager for profile building
 364→    if (this.cognitiveManager) {
 365→      this.cognitiveManager.onLegacyQuestionAnswered(question.id, answer);
 366→    }
 367→
 368→    // EVOLVE the graphics — pass question.id for plant type selection
 369→    this.evolve(game, question.depth, parseFloat(data.trait), question.id);
 370→
 371→    this.currentQuestionIndex++;
 372→
 373→    // Dramatic pause scales with depth
 374→    const pauseDuration = 200 + question.depth * 100;
 375→    setTimeout(() => {
 376→      this.showQuestion(game, this.currentQuestionIndex);
 377→    }, pauseDuration);
 378→  }
 379→
 380→  /**
 381→   * CORE EVOLUTION FUNCTION
 382→   * Called after each answer — makes the garden grow
 383→   *
 384→   * MAC-CENTRIC GROWTH: Plants spawn in rings that converge toward the Mac.
 385→   * Earlier questions = plants at edges of screen (large radius)
 386→   * Later questions = plants close to the Mac (small radius)
 387→   *
 388→   * This creates the effect of the garden "enveloping" the computer.
 389→   */
 390→  evolve(game, depth, traitValue, questionId) {
 391→    // Base evolution progress (0 to 1 over all questions)
 392→    this.targetEvolution = (this.currentQuestionIndex + 1) / QUESTIONS.length;
 393→
 394→    // Stage-specific evolution (2 questions per stage)
 395→    const newStage = Math.ceil((this.currentQuestionIndex + 1) / 2);
 396→    this.stage = newStage;
 397→
 398→    // Brightness increases with evolution
 399→    this.brightness = 0.1 + this.targetEvolution * 0.4;
 400→
 401→    // === MAC-CENTRIC PLANT SPAWNING ===
 402→    // Plants grow FROM edges TOWARD the Mac
 403→    // Earlier questions = far from Mac, later questions = close to Mac
 404→    const plantCount = 3 + Math.floor(Math.random() * 2);
 405→
 406→    // Mac center (where plants converge)
 407→    const macCenterX = this.macBounds.x + this.macBounds.width / 2;
 408→    const macCenterY = this.macBounds.y + this.macBounds.height;
 409→
 410→    // Radius decreases as questions progress (converging on Mac)
 411→    // Q1-2: plants at screen edges (radius ~350-400)
 412→    // Q7-8: plants hugging the Mac (radius ~80-120)
 413→    const progress = this.currentQuestionIndex / (QUESTIONS.length - 1); // 0 to 1
 414→    const maxRadius = Math.min(game.width, game.height) * 0.45;
 415→    const minRadius = this.macBounds.width * 0.6;
 416→    const radius = maxRadius - progress * (maxRadius - minRadius);
 417→
 418→    this.garden.addPlantsAroundCenter(questionId, traitValue, macCenterX, macCenterY, radius, plantCount);
 419→
 420→    // Stage-specific effects
 421→    switch (newStage) {
 422→      case 1: // SEEDS — First stirrings of life
 423→        // Subtle, just the first plants
 424→        break;
 425→
 426→      case 2: // SPROUTS — More growth, some fireflies appear
 427→        if (Math.random() < 0.4) {
 428→          const fx = game.width * 0.2 + Math.random() * game.width * 0.6;
 429→          const fy = this.groundY - 80 - Math.random() * 100;
 430→          this.garden.addFirefly(fx, fy);
 431→        }
 432→        break;
 433→
 434→      case 3: // BLOOM — Garden flourishes, more fireflies
 435→        for (let i = 0; i < 2; i++) {
 436→          if (Math.random() < 0.5) {
 437→            const fx = game.width * 0.1 + Math.random() * game.width * 0.8;
 438→            const fy = this.groundY - 60 - Math.random() * 120;
 439→            this.garden.addFirefly(fx, fy);
 440→          }
 441→        }
 442→        this.ambientGlow = 0.1 + traitValue * 0.1;
 443→        break;
 444→
 445→      case 4: // GLOW — Full bioluminescence
 446→        this.ambientGlow = 0.3 + traitValue * 0.2;
 447→        // Extra fireflies for the finale
 448→        for (let i = 0; i < 3; i++) {
 449→          const fx = game.width * 0.1 + Math.random() * game.width * 0.8;
 450→          const fy = this.groundY - 50 - Math.random() * 150;
 451→          this.garden.addFirefly(fx, fy);
 452→        }
 453→        break;
 454→    }
 455→  }
 456→
 457→  // === COGNITIVE QUESTION PHASE ===
 458→  // Deep cognitive profiling questions (optional, after legacy 8)
 459→
 460→  showCognitiveQuestion(game) {
 461→    // Get next cognitive question
 462→    const cogQ = this.cognitiveManager.getNextCognitiveQuestion();
 463→
 464→    // If no more questions or profile is viable, finish
 465→    if (!cogQ) {
 466→      this.phase = 'complete';
 467→      this.finishCalibration(game);
 468→      return;
 469→    }
 470→
 471→    this.currentCognitiveQuestion = cogQ;
 472→    const formatted = formatCognitiveQuestionForDisplay(cogQ);
 473→
 474→    const overlay = this.container.querySelector('#questionOverlay');
 475→    const progress = this.container.querySelector('#progress');
 476→    const depth = this.container.querySelector('#depth');
 477→    const text = this.container.querySelector('#questionText');
 478→    const options = this.container.querySelector('#options');
 479→
 480→    // Update UI
 481→    const totalQ = QUESTIONS.length + this.cognitiveManager.profile.questionsAnswered + 1;
 482→    const currentQ = QUESTIONS.length + this.cognitiveManager.profile.questionsAnswered + 1;
 483→    progress.textContent = `${currentQ}/${totalQ}+`;
 484→
 485→    depth.textContent = getCognitiveDepthLabel(cogQ.tier);
 486→    depth.className = `question-depth depth-${formatted.depth}`;
 487→
 488→    text.textContent = formatted.text;
 489→
 490→    // Create option buttons
 491→    options.textContent = ''; // Clear existing
 492→    formatted.options.forEach((opt, i) => {
 493→      const btn = document.createElement('button');
 494→      btn.className = 'mac-option';
 495→      btn.dataset.index = i;
 496→      btn.textContent = opt.label;
 497→      btn.onclick = () => this.selectCognitiveAnswer(game, cogQ.id, i);
 498→      options.appendChild(btn);
 499→    });
 500→
 501→    // Fade in
 502→    overlay.classList.remove('visible');
 503→    setTimeout(() => overlay.classList.add('visible'), 50);
 504→  }
 505→
 506→  selectCognitiveAnswer(game, questionId, optionIndex) {
 507→    // Score the answer
 508→    this.cognitiveManager.answerCognitiveQuestion(questionId, optionIndex);
 509→
 510→    // Continue garden evolution (smaller increments for cognitive questions)
 511→    const depth = 3; // Treat as mid-depth
 512→    const trait = 0.5; // Neutral trait for visual
 513→    this.evolve(game, depth, trait, `cognitive_${questionId}`);
 514→
 515→    // Show next question after pause
 516→    setTimeout(() => {
 517→      this.showCognitiveQuestion(game);
 518→    }, 400);
 519→  }
 520→
 521→  finishCalibration(game) {
 522→    // === DETERMINISTIC PROFILE (Legacy) ===
 523→    // Use DeterministicProfileEngine for invariant trait computation
 524→    // Same answers → Same profile. Always.
 525→    const profile = DeterministicProfileEngine.buildProfile(this.answers);
 526→
 527→    // Add confidence based on answer completeness
 528→    profile.confidence = DeterministicProfileEngine.computeConfidence(this.answers);
 529→
 530→    // === COGNITIVE PROFILE ===
 531→    // End the cognitive session and save to storage
 532→    if (this.cognitiveManager) {
 533→      const cognitiveProfile = this.cognitiveManager.endSession();
 534→      this.cognitiveManager.saveToStorage();
 535→
 536→      // Attach cognitive profile to main profile
 537→      profile.cognitive = cognitiveProfile;
 538→      profile.cognitiveInsights = this.cognitiveManager.scoringEngine
 539→        ? this.cognitiveManager.scoringEngine.analyzeEmergentPatterns(cognitiveProfile)
 540→        : [];
 541→    }
 542→
 543→    // === AESTHETIC SIGNATURE ===
 544→    // Visual signature is for display only — NOT used in AI behavior
 545→    // Garden metrics are random, so we only capture color state
 546→    profile.visualSignature = {
 547→      hue: this.colorHue,
 548→      saturation: this.colorSaturation,
 549→      brightness: this.brightness,
 550→      stage: this.stage,
 551→      // Note: Garden counts removed from profile — they're non-deterministic
 552→      // The garden is aesthetic pleasure, the profile is behavioral truth
 553→    };
 554→
 555→    game.calibrationProfile = profile;
 556→    game.changeState('profile');
 557→  }
 558→
 559→  // === UPDATE ===
 560→
 561→  update(game, dt) {
 562→    this.time += dt;
 563→
 564→    // Smooth evolution interpolation
 565→    this.evolution += (this.targetEvolution - this.evolution) * dt * 2;
 566→
 567→    // Wind animation
 568→    this.windPhase += dt * 0.8;
 569→
 570→    // Update stars
 571→    this.updateStars(dt);
 572→
 573→    // Update pixel garden with cursor position for presence response
 574→    if (this.garden) {
 575→      this.garden.setCursor(this.cursorX, this.cursorY);
 576→      this.garden.update(dt, this.time);
 577→    }
 578→  }
 579→
 580→  // ZEN: Track cursor for presence response
 581→  onPointerMove(game, x, y) {
 582→    this.cursorX = x;
 583→    this.cursorY = y;
 584→  }
 585→
 586→  updateStars(dt) {
 587→    // Stars twinkle and fade in with evolution
 588→    this.stars.forEach(star => {
 589→      star.twinklePhase += star.twinkleSpeed * dt;
 590→    });
 591→  }
 592→
 593→  // === RENDER ===
 594→
 595→  render(game, ctx) {
 596→    // === BACKGROUND ===
 597→    // Deep void black with subtle green tint
 598→    ctx.fillStyle = PALETTE.void;
 599→    ctx.fillRect(0, 0, game.width, game.height);
 600→
 601→    // Stars (fade in with evolution)
 602→    this.renderStars(ctx, game);
 603→
 604→    // Subtle glow from garden center (grows with evolution)
 605→    if (this.evolution > 0.2) {
 606→      const gradient = ctx.createRadialGradient(
 607→        game.width / 2, this.groundY, 0,
 608→        game.width / 2, this.groundY, game.height * 0.6
 609→      );
 610→      const glowAlpha = 0.05 + this.evolution * 0.1 + this.ambientGlow * 0.15;
 611→      gradient.addColorStop(0, `rgba(90, 186, 90, ${glowAlpha})`);
 612→      gradient.addColorStop(1, 'transparent');
 613→      ctx.fillStyle = gradient;
 614→      ctx.fillRect(0, 0, game.width, game.height);
 615→    }
 616→
 617→    // === GROUND ===
 618→    this.renderGround(ctx, game);
 619→
 620→    // === PIXEL GARDEN ===
 621→    // Initialize renderer if needed
 622→    if (this.garden && !this.garden.renderer) {
 623→      this.garden.setRenderer(ctx, 3); // 3px pixel size
 624→    }
 625→    if (this.garden) {
 626→      this.garden.render(this.time);
 627→    }
 628→
 629→    // === AMBIENT GLOW (stage 4) ===
 630→    if (this.ambientGlow > 0) {
 631→      this.renderBioluminescence(ctx, game);
 632→    }
 633→
 634→    // === MAC ===
 635→    this.renderMac(ctx, game);
 636→
 637→    // === POST-PROCESSING: VIGNETTE ===
 638→    // Darkens edges to focus attention on center
 639→    this.renderVignette(ctx, game);
 640→  }
 641→
 642→  // IMPACT: Post-processing vignette effect
 643→  renderVignette(ctx, game) {
 644→    const gradient = ctx.createRadialGradient(
 645→      game.width / 2, game.height / 2, game.height * 0.25,
 646→      game.width / 2, game.height / 2, game.height * 0.9
 647→    );
 648→    gradient.addColorStop(0, 'rgba(0,0,0,0)');
 649→    gradient.addColorStop(0.5, 'rgba(0,0,0,0.1)');
 650→    gradient.addColorStop(1, 'rgba(0,0,0,0.5)');
 651→    ctx.fillStyle = gradient;
 652→    ctx.fillRect(0, 0, game.width, game.height);
 653→  }
 654→
 655→  renderGround(ctx, game) {
 656→    // Ground gradient - dark soil fading to black
 657→    const groundGradient = ctx.createLinearGradient(0, this.groundY - 20, 0, game.height);
 658→    groundGradient.addColorStop(0, 'transparent');
 659→    groundGradient.addColorStop(0.1, PALETTE.darkest);
 660→    groundGradient.addColorStop(1, PALETTE.void);
 661→
 662→    ctx.fillStyle = groundGradient;
 663→    ctx.fillRect(0, this.groundY - 20, game.width, game.height - this.groundY + 20);
 664→
 665→    // Ground line (subtle)
 666→    ctx.fillStyle = PALETTE.darker;
 667→    ctx.fillRect(0, this.groundY, game.width, 3);
 668→  }
 669→
 670→  renderBioluminescence(ctx, game) {
 671→    // Overall ambient glow that pulses
 672→    const pulse = 0.7 + Math.sin(this.time * 0.5) * 0.3;
 673→
 674→    const gradient = ctx.createRadialGradient(
 675→      game.width / 2, this.groundY - 50, 0,
 676→      game.width / 2, this.groundY - 50, game.width * 0.5
 677→    );
 678→    gradient.addColorStop(0, `rgba(90, 186, 90, ${this.ambientGlow * 0.1 * pulse})`);
 679→    gradient.addColorStop(1, 'transparent');
 680→
 681→    ctx.fillStyle = gradient;
 682→    ctx.fillRect(0, 0, game.width, game.height);
 683→  }
 684→
 685→  renderStars(ctx, game) {
 686→    // Stars fade in with evolution — the sky awakens
 687→    const starAlpha = Math.max(0, (this.evolution - 0.1) * 1.2);
 688→    if (starAlpha <= 0) return;
 689→
 690→    this.stars.forEach(star => {
 691→      const twinkle = 0.5 + Math.sin(star.twinklePhase) * 0.5;
 692→      const alpha = starAlpha * star.brightness * twinkle;
 693→
 694→      // Star glow (stage 3+)
 695→      if (this.stage >= 3) {
 696→        ctx.fillStyle = `rgba(170, 255, 170, ${alpha * 0.2})`;
 697→        ctx.beginPath();
 698→        ctx.arc(star.x, star.y, star.size * 3, 0, Math.PI * 2);
 699→        ctx.fill();
 700→      }
 701→
 702→      // Star core
 703→      ctx.fillStyle = `rgba(170, 255, 170, ${alpha})`;
 704→      ctx.beginPath();
 705→      ctx.arc(star.x, star.y, star.size, 0, Math.PI * 2);
 706→      ctx.fill();
 707→    });
 708→  }
 709→
 710→  renderMac(ctx, game) {
 711→    const m = this.macBounds;
 712→    const s = this.screenBounds;
 713→
 714→    // === 3D CABINET PROJECTION ===
 715→    // Depth recedes at 30 degrees up-right (consistent vanishing direction)
 716→    const depth = m.height * 0.12;
 717→    const depthX = depth * 0.866; // cos(30°)
 718→    const depthY = depth * 0.5;   // sin(30°)
 719→
 720→    // === 1. GROUND SHADOW ===
 721→    ctx.save();
 722→    const shadowGrad = ctx.createRadialGradient(
 723→      m.x + m.width / 2, m.y + m.height + 8,
 724→      m.width * 0.1,
 725→      m.x + m.width / 2, m.y + m.height + 8,
 726→      m.width * 0.6
 727→    );
 728→    shadowGrad.addColorStop(0, 'rgba(0, 0, 0, 0.5)');
 729→    shadowGrad.addColorStop(0.5, 'rgba(0, 0, 0, 0.2)');
 730→    shadowGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');
 731→    ctx.fillStyle = shadowGrad;
 732→    ctx.beginPath();
 733→    ctx.ellipse(m.x + m.width / 2, m.y + m.height + 8, m.width * 0.55, 12, 0, 0, Math.PI * 2);
 734→    ctx.fill();
 735→    ctx.restore();
 736→
 737→    // === 2. BACK EDGES (draw first, behind everything) ===
 738→    // These create the illusion of depth by showing where the back of the box would be
 739→
 740→    // === 3. RIGHT SIDE PANEL (visible depth - shadow side) ===
 741→    ctx.beginPath();
 742→    ctx.moveTo(m.x + m.width, m.y + 8);                           // Front top-right
 743→    ctx.lineTo(m.x + m.width + depthX, m.y + 8 - depthY);         // Back top-right
 744→    ctx.lineTo(m.x + m.width + depthX, m.y + m.height - 8 - depthY); // Back bottom-right
 745→    ctx.lineTo(m.x + m.width, m.y + m.height - 8);                // Front bottom-right
 746→    ctx.closePath();
 747→
 748→    // Gradient from front (lighter) to back (darker)
 749→    const sideGrad = ctx.createLinearGradient(
 750→      m.x + m.width, m.y,
 751→      m.x + m.width + depthX, m.y - depthY
 752→    );
 753→    sideGrad.addColorStop(0, '#c8c0b0');
 754→    sideGrad.addColorStop(1, '#a8a090');
 755→    ctx.fillStyle = sideGrad;
 756→    ctx.fill();
 757→    ctx.strokeStyle = '#706860';
 758→    ctx.lineWidth = 1;
 759→    ctx.stroke();
 760→
 761→    // === 4. TOP PANEL (visible depth - lit side) ===
 762→    ctx.beginPath();
 763→    ctx.moveTo(m.x + 8, m.y);                                     // Front top-left
 764→    ctx.lineTo(m.x + 8 + depthX, m.y - depthY);                   // Back top-left
 765→    ctx.lineTo(m.x + m.width - 8 + depthX, m.y - depthY);         // Back top-right
 766→    ctx.lineTo(m.x + m.width + depthX, m.y + 8 - depthY);         // Connect to side
 767→    ctx.lineTo(m.x + m.width, m.y + 8);                           // Front top-right corner
 768→    ctx.lineTo(m.x + m.width - 8, m.y);                           // Front top-right
 769→    ctx.closePath();
 770→
 771→    // Top catches light
 772→    const topGrad = ctx.createLinearGradient(
 773→      m.x, m.y,
 774→      m.x + depthX, m.y - depthY
 775→    );
 776→    topGrad.addColorStop(0, '#f0e8d8');
 777→    topGrad.addColorStop(1, '#e0d8c8');
 778→    ctx.fillStyle = topGrad;
 779→    ctx.fill();
 780→    ctx.strokeStyle = '#b0a898';
 781→    ctx.lineWidth = 1;
 782→    ctx.stroke();
 783→
 784→    // === 5. FRONT FACE (main body) ===
 785→    const bodyGrad = ctx.createLinearGradient(m.x, m.y, m.x, m.y + m.height);
 786→    bodyGrad.addColorStop(0, '#f5ede0');
 787→    bodyGrad.addColorStop(0.4, '#e8e0d0');
 788→    bodyGrad.addColorStop(1, '#d8d0c0');
 789→    ctx.fillStyle = bodyGrad;
 790→    ctx.strokeStyle = '#504840';
 791→    ctx.lineWidth = 2;
 792→    this.roundRect(ctx, m.x, m.y, m.width, m.height, 8);
 793→    ctx.fill();
 794→    ctx.stroke();
 795→
 796→    // Front face bevel highlights
 797→    ctx.strokeStyle = 'rgba(255,255,255,0.4)';
 798→    ctx.lineWidth = 2;
 799→    ctx.beginPath();
 800→    ctx.moveTo(m.x + 8, m.y + 2);
 801→    ctx.lineTo(m.x + m.width - 8, m.y + 2);
 802→    ctx.stroke();
 803→    ctx.beginPath();
 804→    ctx.moveTo(m.x + 2, m.y + 8);
 805→    ctx.lineTo(m.x + 2, m.y + m.height - 8);
 806→    ctx.stroke();
 807→
 808→    // Front face shadow edges
 809→    ctx.strokeStyle = 'rgba(0,0,0,0.15)';
 810→    ctx.lineWidth = 2;
 811→    ctx.beginPath();
 812→    ctx.moveTo(m.x + 8, m.y + m.height - 2);
 813→    ctx.lineTo(m.x + m.width - 8, m.y + m.height - 2);
 814→    ctx.stroke();
 815→    ctx.beginPath();
 816→    ctx.moveTo(m.x + m.width - 2, m.y + 8);
 817→    ctx.lineTo(m.x + m.width - 2, m.y + m.height - 8);
 818→    ctx.stroke();
 819→
 820→    // === 6. SCREEN BEZEL (recessed) ===
 821→    // Outer bezel (dark recess)
 822→    ctx.fillStyle = '#0a0a0a';
 823→    this.roundRect(ctx, s.x - 6, s.y - 6, s.width + 12, s.height + 12, 4);
 824→    ctx.fill();
 825→
 826→    // Bezel rim with 3D inset effect
 827→    ctx.strokeStyle = '#404040';
 828→    ctx.lineWidth = 1;
 829→    ctx.beginPath();
 830→    ctx.moveTo(s.x - 5, s.y + s.height + 5);
 831→    ctx.lineTo(s.x - 5, s.y - 5);
 832→    ctx.lineTo(s.x + s.width + 5, s.y - 5);
 833→    ctx.stroke();
 834→    ctx.strokeStyle = '#1a1a1a';
 835→    ctx.beginPath();
 836→    ctx.moveTo(s.x + s.width + 5, s.y - 5);
 837→    ctx.lineTo(s.x + s.width + 5, s.y + s.height + 5);
 838→    ctx.lineTo(s.x - 5, s.y + s.height + 5);
 839→    ctx.stroke();
 840→
 841→    // === 7. CRT SCREEN ===
 842→    ctx.fillStyle = '#0a150a';
 843→    ctx.fillRect(s.x, s.y, s.width, s.height);
 844→
 845→    // CRT glass curvature (darker at edges)
 846→    const crtCurve = ctx.createRadialGradient(
 847→      s.x + s.width / 2, s.y + s.height / 2, 0,
 848→      s.x + s.width / 2, s.y + s.height / 2, s.width * 0.7
 849→    );
 850→    crtCurve.addColorStop(0, 'rgba(0,0,0,0)');
 851→    crtCurve.addColorStop(0.6, 'rgba(0,0,0,0.05)');
 852→    crtCurve.addColorStop(1, 'rgba(0,0,0,0.3)');
 853→    ctx.fillStyle = crtCurve;
 854→    ctx.fillRect(s.x, s.y, s.width, s.height);
 855→
 856→    // Glass reflection
 857→    ctx.fillStyle = 'rgba(120, 180, 120, 0.04)';
 858→    ctx.beginPath();
 859→    ctx.ellipse(s.x + s.width * 0.3, s.y + s.height * 0.25, s.width * 0.4, s.height * 0.2, -0.3, 0, Math.PI * 2);
 860→    ctx.fill();
 861→
 862→    // === 8. PHOSPHOR GLOW ===
 863→    const plantCount = this.garden ? this.garden.getMaturePlantCount() : 0;
 864→    const gardenHealth = Math.min(1, plantCount / 6);
 865→    const breath = Math.sin(this.time * 0.17) * 0.5 + 0.5;
 866→    const glowIntensity = 0.03 + gardenHealth * 0.12 + (gardenHealth > 0.3 ? breath * 0.05 : 0);
 867→
 868→    const glow = ctx.createRadialGradient(
 869→      s.x + s.width / 2, s.y + s.height / 2, 0,
 870→      s.x + s.width / 2, s.y + s.height / 2, s.width * 0.7
 871→    );
 872→    const warmth = 80 + gardenHealth * 40;
 873→    glow.addColorStop(0, `rgba(${warmth}, ${150 + gardenHealth * 50}, ${warmth}, ${glowIntensity})`);
 874→    glow.addColorStop(1, 'transparent');
 875→    ctx.fillStyle = glow;
 876→    ctx.fillRect(s.x, s.y, s.width, s.height);
 877→
 878→    // Scanlines
 879→    ctx.fillStyle = 'rgba(0, 0, 0, 0.05)';
 880→    for (let y = s.y; y < s.y + s.height; y += 3) {
 881→      ctx.fillRect(s.x, y, s.width, 1);
 882→    }
 883→
 884→    // === 9. CHIN AREA ===
 885→    const chinY = s.y + s.height + 10;
 886→
 887→    // Disk slot (3D inset)
 888→    const slotWidth = m.width * 0.20;
 889→    const slotX = m.x + m.width / 2 - slotWidth / 2;
 890→    ctx.fillStyle = '#1a1a1a';
 891→    this.roundRect(ctx, slotX, chinY + 12, slotWidth, 6, 2);
 892→    ctx.fill();
 893→    // Slot top edge shadow
 894→    ctx.strokeStyle = '#303030';
 895→    ctx.lineWidth = 1;
 896→    ctx.beginPath();
 897→    ctx.moveTo(slotX + 2, chinY + 12);
 898→    ctx.lineTo(slotX + slotWidth - 2, chinY + 12);
 899→    ctx.stroke();
 900→    // Slot bottom edge highlight
 901→    ctx.strokeStyle = '#0a0a0a';
 902→    ctx.beginPath();
 903→    ctx.moveTo(slotX + 2, chinY + 17);
 904→    ctx.lineTo(slotX + slotWidth - 2, chinY + 17);
 905→    ctx.stroke();
 906→
 907→    // === 10. VENTS (3D grooves) ===
 908→    const ventCount = 6;
 909→    const ventSpacing = m.height * 0.015;
 910→    const ventStartY = m.y + m.height * 0.05;
 911→
 912→    for (let i = 0; i < ventCount; i++) {
 913→      const vy = ventStartY + i * ventSpacing;
 914→
 915→      // Left vents - shadow then highlight for groove effect
 916→      ctx.strokeStyle = '#a09888';
 917→      ctx.lineWidth = 2;
 918→      ctx.beginPath();
 919→      ctx.moveTo(m.x + 6, vy);
 920→      ctx.lineTo(m.x + 16, vy);
 921→      ctx.stroke();
 922→      ctx.strokeStyle = '#e8e0d0';
 923→      ctx.lineWidth = 1;
 924→      ctx.beginPath();
 925→      ctx.moveTo(m.x + 6, vy + 2);
 926→      ctx.lineTo(m.x + 16, vy + 2);
 927→      ctx.stroke();
 928→
 929→      // Right vents
 930→      ctx.strokeStyle = '#a09888';
 931→      ctx.lineWidth = 2;
 932→      ctx.beginPath();
 933→      ctx.moveTo(m.x + m.width - 16, vy);
 934→      ctx.lineTo(m.x + m.width - 6, vy);
 935→      ctx.stroke();
 936→      ctx.strokeStyle = '#e8e0d0';
 937→      ctx.lineWidth = 1;
 938→      ctx.beginPath();
 939→      ctx.moveTo(m.x + m.width - 16, vy + 2);
 940→      ctx.lineTo(m.x + m.width - 6, vy + 2);
 941→      ctx.stroke();
 942→    }
 943→
 944→    // === 11. SCREEN LIGHT SPILL onto body ===
 945→    if (gardenHealth > 0.2) {
 946→      const spillGrad = ctx.createRadialGradient(
 947→        s.x + s.width / 2, s.y + s.height, 0,
 948→        s.x + s.width / 2, chinY + 40, s.width * 0.4
 949→      );
 950→      spillGrad.addColorStop(0, `rgba(100, 180, 100, ${0.08 * gardenHealth})`);
 951→      spillGrad.addColorStop(1, 'transparent');
 952→      ctx.fillStyle = spillGrad;
 953→      ctx.fillRect(m.x, s.y + s.height, m.width, m.height - (s.y + s.height - m.y));
 954→    }
 955→  }
