143→export class DeterministicProfileEngine {
144→  /**
145→   * Compute traits from raw answers
146→   * PURE FUNCTION — no side effects, deterministic
147→   *
148→   * @param {Object} answers - Raw answer data keyed by question ID
149→   * @returns {Object} Computed traits with values, labels, and behaviors
150→   */
151→  static computeTraits(answers) {
152→    const traits = {};
153→
154→    // Step 1: Aggregate values by dimension
155→    // Process in FIXED ORDER (Object.values maintains insertion order,
156→    // but we sort by dimension for determinism)
157→    const answerList = Object.values(answers);
158→    answerList.sort((a, b) => a.dimension.localeCompare(b.dimension));
159→
160→    answerList.forEach(answer => {
161→      const dim = answer.dimension;
162→      if (!traits[dim]) {
163→        traits[dim] = {
164→          values: [],
165→          depth: answer.depth
166→        };
167→      }
168→      traits[dim].values.push(answer.trait);
169→    });
170→
171→    // Step 2: Compute final values (average)
172→    // Process dimensions in ALPHABETICAL ORDER for determinism
173→    const sortedDims = Object.keys(traits).sort();
174→
175→    sortedDims.forEach(dim => {
176→      const trait = traits[dim];
177→      const avg = trait.values.reduce((a, b) => a + b, 0) / trait.values.length;
178→
179→      // Round to 2 decimal places for consistency
180→      trait.value = Math.round(avg * 100) / 100;
181→
182→      // Get label and behavior from config
183→      const config = DIMENSION_CONFIG[dim];
184→      if (config) {
185→        if (trait.value > 0.6) {
186→          trait.label = config.high.label;
187→          trait.behavior = config.high.behavior;
188→        } else if (trait.value < 0.4) {
189→          trait.label = config.low.label;
190→          trait.behavior = config.low.behavior;
191→        } else {
192→          trait.label = config.mid.label;
193→          trait.behavior = config.mid.behavior;
194→        }
195→      } else {
196→        trait.label = 'Balanced';
197→        trait.behavior = 'Adapt to context';
198→      }
199→
200→      // Remove intermediate values array (not needed in output)
201→      delete trait.values;
202→    });
203→
204→    return traits;
205→  }
206→
207→  /**
208→   * Generate insights from trait patterns
209→   * PURE FUNCTION — deterministic rule matching
210→   *
211→   * @param {Object} traits - Computed traits
212→   * @returns {string[]} Array of insight strings (max 4)
213→   */
214→  static generateInsights(traits) {
215→    const insights = [];
216→
217→    // Apply rules in FIXED ORDER
218→    INSIGHT_RULES.forEach(rule => {
219→      if (insights.length < 4 && rule.condition(traits)) {
220→        insights.push(rule.text);
221→      }
222→    });
223→
224→    // Fallback if no rules matched
225→    if (insights.length === 0) {
226→      insights.push("You adapt fluidly to different communication styles");
227→    }
228→
229→    return insights;
230→  }
231→
232→  /**
233→   * Compute checksum for profile integrity verification
234→   * DETERMINISTIC — same traits → same checksum
235→   *
236→   * @param {Object} traits - Computed traits
237→   * @returns {string} 8-character hex checksum
238→   */
239→  static computeChecksum(traits) {
240→    // Serialize traits in FIXED ORDER
241→    const sortedDims = Object.keys(traits).sort();
242→    const serialized = sortedDims.map(dim => {
243→      const t = traits[dim];
244→      // Use fixed precision to avoid floating-point variance
245→      return `${dim}:${(t.value * 100).toFixed(0)}`;
246→    }).join('|');
247→
248→    // Add version prefix for future compatibility
249→    const versioned = `${VERSION.checksumPrefix}|${serialized}`;
250→
251→    // Compute hash
252→    const hash = djb2Hash(versioned);
253→
254→    return toHex(hash);
255→  }
256→
257→  /**
258→   * Generate semantic anchor for AI recognition
259→   * Format: [TRANSLATORS:<checksum>]
260→   *
261→   * @param {string} checksum - Profile checksum
262→   * @returns {string} Anchor string
263→   */
264→  static generateAnchor(checksum) {
265→    return `[TRANSLATORS:${checksum}]`;
266→  }
267→
268→  /**
269→   * Build complete profile from answers
270→   * Main entry point — orchestrates all computations
271→   *
272→   * @param {Object} answers - Raw answer data
273→   * @returns {Object} Complete deterministic profile
274→   */
275→  static buildProfile(answers) {
276→    // Step 1: Compute traits (deterministic)
277→    const traits = this.computeTraits(answers);
278→
279→    // Step 2: Generate insights (deterministic)
280→    const insights = this.generateInsights(traits);
281→
282→    // Step 3: Compute checksum (deterministic)
283→    const checksum = this.computeChecksum(traits);
284→
285→    // Step 4: Generate anchor (deterministic)
286→    const anchor = this.generateAnchor(checksum);
287→
288→    return {
289→      version: VERSION.profile,
290→      generator: VERSION.generator,
291→      traits,
292→      insights,
293→      checksum,
294→      anchor,
295→      raw: answers
296→    };
297→  }
298→
299→  /**
300→   * Verify profile integrity using checksum
301→   *
302→   * @param {Object} profile - Profile to verify
303→   * @returns {boolean} True if checksum matches
304→   */
305→  static verifyIntegrity(profile) {
306→    const computedChecksum = this.computeChecksum(profile.traits);
307→    return computedChecksum === profile.checksum;
308→  }
309→
310→  /**
311→   * Validate profile structure and integrity
312→   * Use before export to prevent undefined/corrupted data
313→   *
314→   * @param {Object} profile - Profile to validate
315→   * @returns {Object} { valid: boolean, errors: string[] }
316→   */
317→  static validateProfile(profile) {
318→    const errors = [];
319→
320→    if (!profile) {
321→      errors.push('Profile is null or undefined');
322→      return { valid: false, errors };
323→    }
324→
325→    if (!profile.traits || typeof profile.traits !== 'object') {
326→      errors.push('Missing or invalid traits object');
327→    }
328→
329→    if (!profile.checksum || typeof profile.checksum !== 'string') {
330→      errors.push('Missing or invalid checksum');
331→    }
332→
333→    if (!profile.anchor || typeof profile.anchor !== 'string') {
334→      errors.push('Missing or invalid anchor');
335→    }
336→
337→    // Validate each trait has required fields
338→    if (profile.traits) {
339→      Object.entries(profile.traits).forEach(([dim, trait]) => {
340→        if (typeof trait.value !== 'number') {
341→          errors.push(`Trait '${dim}' missing numeric value`);
342→        }
343→        if (typeof trait.label !== 'string') {
344→          errors.push(`Trait '${dim}' missing label`);
345→        }
346→        if (typeof trait.behavior !== 'string') {
347→          errors.push(`Trait '${dim}' missing behavior`);
348→        }
349→      });
350→    }
351→
352→    return { valid: errors.length === 0, errors };
353→  }
354→
355→  /**
356→   * Get confidence level based on answer consistency
357→   * Higher consistency = higher confidence
358→   *
359→   * @param {Object} answers - Raw answers
360→   * @returns {number} Confidence 0-1
361→   */
362→  static computeConfidence(answers) {
363→    // Single play = base confidence
364→    // Could be extended for multi-session tracking
365→    const answerCount = Object.keys(answers).length;
366→    const expectedCount = 8;
367→
368→    // Full interview = high confidence
369→    if (answerCount >= expectedCount) {
370→      return 0.85;
371→    }
372→
373→    // Partial interview = scaled confidence
374→    return 0.4 + (answerCount / expectedCount) * 0.45;
375→  }
376→}
