  1→/**
  2→ * Behavior Tracker — The Translators
  3→ * Source: GAME_SPEC.md "What Gets Measured" sections
  4→ * 
  5→ * Central system for tracking all player behaviors across layers.
  6→ * States should call tracker methods, not modify data directly.
  7→ */
  8→
  9→import { PHYSICS } from '../config/physics.js';
 10→
 11→export class BehaviorTracker {
 12→  constructor() {
 13→    this.reset();
 14→  }
 15→
 16→  /**
 17→   * Reset all tracking data
 18→   */
 19→  reset() {
 20→    // === v2: Character Selection ===
 21→    this.selectedCharacter = null;
 22→    this.characterSelectTime = 0;
 23→    this.characterHoverHistory = [];
 24→
 25→    // === v2: Garden Moments ===
 26→    this.momentData = []; // Array of moment recordings
 27→    this.placements = []; // All object placements
 28→    this.placementSpeeds = [];
 29→    this.momentDurations = [];
 30→    this.revisionCounts = [];
 31→    this.categorySelections = {};
 32→    this.firstChoices = [];
 33→
 34→    // Legacy: Layer 1: Exploration
 35→    this.pathLength = 0;
 36→    this.lastPosition = { x: 0, y: 0 };
 37→    this.orbsCollected = 0;
 38→    this.orbsTotal = 8;
 39→
 40→    // Legacy: Layer 2: Arrangement
 41→    this.arrangeActions = 0;
 42→    this.firstActionTime = null;
 43→    this.layerStartTime = 0;
 44→    this.elementPositions = []; // For analysis
 45→
 46→    // Legacy: Layer 3: Communication
 47→    this.mirrorCount = 0;
 48→    this.interpretCount = 0;
 49→    this.contrastCount = 0;
 50→    this.responseTimes = [];
 51→  }
 52→
 53→  // === v2: Character Selection Methods ===
 54→
 55→  /**
 56→   * Record character selection with timing and hover data
 57→   * @param {string} characterId - Selected character ID
 58→   * @param {number} selectTime - Time to select (ms from start)
 59→   * @param {Array} hoverHistory - Array of hover events
 60→   */
 61→  recordCharacterSelection(characterId, selectTime, hoverHistory) {
 62→    this.selectedCharacter = characterId;
 63→    this.characterSelectTime = selectTime;
 64→    this.characterHoverHistory = hoverHistory;
 65→  }
 66→
 67→  /**
 68→   * Analyze hover behavior for exploration signal
 69→   * Higher exploration = more hovering before deciding
 70→   */
 71→  getCharacterExplorationSignal() {
 72→    if (!this.characterHoverHistory.length) return 0.5;
 73→
 74→    const uniqueHovers = new Set(this.characterHoverHistory.map(h => h.characterId)).size;
 75→    const totalHoverTime = this.characterHoverHistory.reduce((sum, h) => sum + h.duration, 0);
 76→    const hoverCount = this.characterHoverHistory.length;
 77→
 78→    // More unique characters hovered = more exploration
 79→    // More total hover time = more exploration
 80→    // Quick decision = less exploration
 81→
 82→    const explorationScore = Math.min(1, (
 83→      (uniqueHovers / 4) * 0.4 +              // Coverage factor
 84→      Math.min(1, totalHoverTime / 5000) * 0.3 + // Time factor
 85→      Math.min(1, hoverCount / 6) * 0.3        // Revisit factor
 86→    ));
 87→
 88→    return explorationScore;
 89→  }
 90→
 91→  // === v2: Garden Placement Methods ===
 92→
 93→  /**
 94→   * Record an object placement
 95→   * @param {object} data - Placement data
 96→   */
 97→  recordPlacement(data) {
 98→    const { objectId, category, position, momentIndex, timestamp, isFirst } = data;
 99→
100→    this.placements.push({
101→      objectId,
102→      category,
103→      position,
104→      momentIndex,
105→      timestamp
106→    });
107→
108→    // Track category selections
109→    if (!this.categorySelections[category]) {
110→      this.categorySelections[category] = 0;
111→    }
112→    this.categorySelections[category]++;
113→
114→    // Track first choices
115→    if (isFirst) {
116→      this.firstChoices.push({ objectId, category, momentIndex });
117→    }
118→  }
119→
120→  /**
121→   * Record placement speed (time between placements)
122→   * @param {number} speed - Time in ms
123→   */
124→  recordPlacementSpeed(speed) {
125→    this.placementSpeeds.push(speed);
126→  }
127→
128→  /**
129→   * Record moment completion
130→   * @param {object} data - Moment data
131→   */
132→  recordMomentComplete(data) {
133→    const { momentIndex, duration, placementCount, revisions, ambiguityResponse } = data;
134→
135→    this.momentData.push({
136→      momentIndex,
137→      duration,
138→      placementCount,
139→      revisions,
140→      ambiguityResponse
141→    });
142→
143→    this.momentDurations.push(duration);
144→    this.revisionCounts.push(revisions || 0);
145→  }
146→
147→  // === v2: Analysis Methods ===
148→
149→  /**
150→   * Get placement style based on spatial distribution
151→   * @returns {string} 'clustered' | 'spread' | 'structured' | 'organic'
152→   */
153→  getPlacementStyle() {
154→    if (this.placements.length < 3) return 'organic';
155→
156→    const positions = this.placements.map(p => p.position);
157→
158→    // Calculate centroid
159→    const cx = positions.reduce((s, p) => s + p.x, 0) / positions.length;
160→    const cy = positions.reduce((s, p) => s + p.y, 0) / positions.length;
161→
162→    // Calculate spread from centroid
163→    const avgDist = positions.reduce((s, p) => {
164→      return s + Math.sqrt((p.x - cx) ** 2 + (p.y - cy) ** 2);
165→    }, 0) / positions.length;
166→
167→    // Check for alignment (structured)
168→    let alignedH = 0, alignedV = 0;
169→    for (let i = 0; i < positions.length; i++) {
170→      for (let j = i + 1; j < positions.length; j++) {
171→        if (Math.abs(positions[i].y - positions[j].y) < 40) alignedH++;
172→        if (Math.abs(positions[i].x - positions[j].x) < 40) alignedV++;
173→      }
174→    }
175→
176→    const pairCount = (positions.length * (positions.length - 1)) / 2;
177→    const alignmentRatio = (alignedH + alignedV) / (pairCount * 2);
178→
179→    if (alignmentRatio > 0.4) return 'structured';
180→    if (avgDist < 100) return 'clustered';
181→    if (avgDist > 250) return 'spread';
182→    return 'organic';
183→  }
184→
185→  /**
186→   * Get decision speed category
187→   * @returns {string} 'quick' | 'measured' | 'deliberate'
188→   */
189→  getDecisionSpeed() {
190→    if (this.placementSpeeds.length < 2) {
191→      // Fall back to moment durations
192→      if (this.momentDurations.length === 0) return 'measured';
193→      const avgDuration = this.momentDurations.reduce((a, b) => a + b, 0) / this.momentDurations.length;
194→      if (avgDuration < 8000) return 'quick';
195→      if (avgDuration > 20000) return 'deliberate';
196→      return 'measured';
197→    }
198→
199→    const avgSpeed = this.placementSpeeds.reduce((a, b) => a + b, 0) / this.placementSpeeds.length;
200→
201→    if (avgSpeed < 2000) return 'quick';
202→    if (avgSpeed > 5000) return 'deliberate';
203→    return 'measured';
204→  }
205→
206→  /**
207→   * Get iteration style based on revision behavior
208→   * @returns {string} 'iterative' | 'decisive' | 'exploratory'
209→   */
210→  getIterationStyle() {
211→    if (this.revisionCounts.length === 0) return 'decisive';
212→
213→    const avgRevisions = this.revisionCounts.reduce((a, b) => a + b, 0) / this.revisionCounts.length;
214→
215→    if (avgRevisions < 0.5) return 'decisive';
216→    if (avgRevisions > 2) return 'exploratory';
217→    return 'iterative';
218→  }
219→
220→  /**
221→   * Get edge preference (placements near canvas edges)
222→   * @param {number} canvasWidth
223→   * @param {number} canvasHeight
224→   * @returns {number} 0-1 score (higher = more edge preference)
225→   */
226→  getEdgePreference(canvasWidth, canvasHeight) {
227→    if (this.placements.length === 0) return 0.5;
228→
229→    const edgeThreshold = 100;
230→    let edgePlacements = 0;
231→
232→    this.placements.forEach(p => {
233→      if (p.position.x < edgeThreshold ||
234→          p.position.x > canvasWidth - edgeThreshold ||
235→          p.position.y < edgeThreshold ||
236→          p.position.y > canvasHeight - edgeThreshold) {
237→        edgePlacements++;
238→      }
239→    });
240→
241→    return edgePlacements / this.placements.length;
242→  }
