244→  // === Layer 1 Methods ===
245→
246→  /**
247→   * Initialize path tracking
248→   */
249→  initPathTracking(x, y) {
250→    this.lastPosition = { x, y };
251→  }
252→
253→  /**
254→   * Track movement for path length calculation
255→   */
256→  trackPath(x, y) {
257→    const dx = x - this.lastPosition.x;
258→    const dy = y - this.lastPosition.y;
259→    this.pathLength += Math.sqrt(dx * dx + dy * dy);
260→    this.lastPosition = { x, y };
261→  }
