270→  /**
271→   * Get exploration score (0-1)
272→   * Higher = more exploration (less direct path)
273→   */
274→  getExplorationScore(directDistance) {
275→    const efficiency = directDistance / Math.max(this.pathLength, directDistance);
276→    return 1 - efficiency;
277→  }
