1098→export const DOMAIN_QUESTIONS = ALL_QUESTIONS.filter(q => q.tier === QuestionTier.DOMAIN);
1099→export const DEEP_QUESTIONS = ALL_QUESTIONS.filter(q => q.tier === QuestionTier.DEEP);
