1101→/**
1102→ * Get the next batch of questions based on profile state
1103→ * @param {Object} profile - Current cognitive profile
1104→ * @param {number} batchSize - Number of questions to return
1105→ * @param {string[]} answeredIds - Question IDs already answered
1106→ */
1107→export function getNextQuestions(profile, batchSize = 3, answeredIds = []) {
1108→  const unanswered = id => !answeredIds.includes(id);
1109→
1110→  // First session: return core questions
1111→  if (profile.questionsAnswered < 12) {
1112→    return CORE_QUESTIONS.filter(q => unanswered(q.id)).slice(0, batchSize);
1113→  }
1114→
1115→  // Subsequent sessions: prioritize underexplored domains
1116→  const { getUnderexploredDomains } = require('./ProfileSchema.js');
1117→  const underexplored = getUnderexploredDomains(profile);
1118→
1119→  if (underexplored.length > 0) {
1120→    const targetDomain = underexplored[0];
1121→    const domainQuestions = QUESTIONS_BY_DOMAIN[targetDomain]
1122→      .filter(q => unanswered(q.id) && q.tier !== QuestionTier.CORE);
1123→
1124→    if (domainQuestions.length >= batchSize) {
1125→      return domainQuestions.slice(0, batchSize);
1126→    }
1127→  }
1128→
1129→  // Fallback: any unanswered domain or deep questions
1130→  return [...DOMAIN_QUESTIONS, ...DEEP_QUESTIONS]
1131→    .filter(q => unanswered(q.id))
1132→    .slice(0, batchSize);
1133→}
1134→
1135→/**
1136→ * Get question by ID
1137→ */
1138→export function getQuestionById(id) {
1139→  return ALL_QUESTIONS.find(q => q.id === id);
1140→}
